const handleSubmit = async (e) => {
  e.preventDefault();

  if (!formData.title.trim()) {
    setError('Task title is required');
    return;
  }

  setLoading(true);
  setError('');

  try {
    let result;

    // 🔥 Map frontend fields to Django fields
    const taskData = {
      User_Task: formData.title,        // Django expects "User_Task"
      descri: formData.description,     // Django expects "descri"
      priority: formData.priority,      // Same name
      status: formData.status || "Today", // Django requires a status (Today/Tomorrow/Advance)
      is_complete: formData.completed,  // Django expects "is_complete"
      // ⚠️ date_time is auto_now_add in Django → you don’t need to send it
    };

    if (User_Task) {
      // Update existing task
      result = await apiService.updateTask(User_Task.id, taskData);
    } else {
      // Create new task
      result = await apiService.createTask(taskData);
    }

    if (result.success) {
      onSave(result.data.data || { ...taskData, id: Date.now() });
    } else {
      setError(result.error || 'Failed to save task');
    }
  } catch (error) {
    console.error('Error saving task:', error);
    setError('Something went wrong. Please try again.');
  } finally {
    setLoading(false);
  }
};
